head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > displayModeSync]<br/>searchTarget='both' 일때 편집 모드의 입력창에 아이템이 표시되는 형식에 displayMode 속성을 적용할지 설정합니다.",
    "validation" : [
        "true 설정 시, 입력창이 편집 모드일때 displayMode 속성을 적용하여 아이템을 표시합니다.",
        "false 설정 시, 입력창이 편집 모드일때 아이템의 Label 을 표시합니다.",
        "미설정 시, 입력창이 편집 모드일때 아이템의 Label 을 표시합니다.",
    ]
}

// 표시값 확인 버튼을 누르는 시점의 입력창 상태
scwin.gVar = { "stateInfo" : "" };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (displayModeSync=true, searchTarget=both, displayMode=value delim label)
    con_displayModeSync.setValue("2");
    con_searchTarget.setValue("both");
    con_displayMode.setValue("value delim label");

    // 표시값 확인 버튼 클릭 시 포커스가 버튼으로 옮겨가 편집 상태가 풀리므로 mousedown capture 단계에서 상태를 기록
    btn_getDisplayInfo.render.addEventListener("mousedown", scwin.captureState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- 아이템(Label / Value) : 서울 / SEL, 부산 / BSN, 대구 / DGU, 인천 / ICN\n- delimiter 는 : 로 고정\n[절차]\n1. 화살표 버튼으로 목록을 열어 아이템 선택 -> 표시값 확인\n2. 값 표시 영역 클릭 -> 입력창이 편집 상태인 채로 표시값 확인"', '', 'label1');

    // 미설정 옵션은 createCList 가 속성에서 제외 (gdl_boolean 은 getText 로 읽는다)
    let properties = {
        displayModeSync : con_displayModeSync.getText(),
        searchTarget : con_searchTarget.getValue(),
        displayMode : con_displayMode.getValue(),
        delimiter : ":",
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>서울</w2:label><w2:value>SEL</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>부산</w2:label><w2:value>BSN</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>대구</w2:label><w2:value>DGU</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>인천</w2:label><w2:value>ICN</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// 버튼 mousedown 시점(포커스가 버튼으로 옮겨가기 전)의 입력창 상태 기록
//  - 편집 상태 : 값 표시 영역이 숨겨지고 입력창이 표시된 상태
scwin.captureState = function (e) {
    let inputElem = document.querySelector("[id='" + target1.id + "_input']");
    let labelElem = document.querySelector("[id='" + target1.id + "_label']");

    if (inputElem.offsetWidth > 0 && labelElem.offsetWidth === 0) {
        scwin.gVar.stateInfo = "편집 상태의 입력창 값 : " + inputElem.value;
    } else {
        scwin.gVar.stateInfo = "입력창 표시 텍스트 : " + labelElem.textContent;
    }
};



// 편집 상태가 아닐 때의 입력창 표시 텍스트 또는 편집 상태의 입력창 값 출력 (validation 1, 2, 3)
scwin.btn_getDisplayInfo_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue(scwin.gVar.stateInfo);
};
